import json
expected_configs = [
    {'file': 'configs/service_01.json', 'retries': 3, 'timeout_seconds': 79},
    {'file': 'configs/service_02.json', 'retries': 6, 'timeout_seconds': 77},
    {'file': 'configs/service_03.json', 'retries': 5, 'timeout_seconds': 35},
    {'file': 'configs/service_04.json', 'retries': 4, 'timeout_seconds': 83}
]
all_correct = True
for config in expected_configs:
    with open(config['file'], 'r') as file:
        data = json.load(file)
    if data['retries'] != config['retries'] or data['timeout_seconds'] != config['timeout_seconds']:
        all_correct = False
        break
if all_correct:
    print('All configurations are correct.')
else:
    print('Some configurations are incorrect.')

import json
configs = ['service_01', 'service_02', 'service_03', 'service_04']
expected_updates = [
    {'enabled': True, 'environment': 'prod', 'retries': 5, 'timeout_seconds': 50},
    {'enabled': True, 'environment': 'prod', 'retries': 2, 'timeout_seconds': 61},
    {'enabled': True, 'environment': 'stage', 'retries': 2, 'timeout_seconds': 49},
    {'enabled': True, 'environment': 'prod', 'retries': 5, 'timeout_seconds': 48}
]
all_correct = True
for config, expected in zip(configs, expected_updates):
    path = f'configs/{config}.json'
    with open(path, 'r') as file:
        data = json.load(file)
    if not all(data.get(key) == value for key, value in expected.items()):
        all_correct = False
        break
if all_correct:
    print('All configurations are correct.')
else:
    print('Some configurations are incorrect.')

